module temperature_shutdown (
    input clk,
    input reset,
    input [7:0] temperature,
    output reg shutdown
);
    parameter THRESHOLD = 8'd80;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            shutdown <= 1'b0;
