                (nearest_y - target_y)*(nearest_y - target_y) < 256) begin
                new_x <= nearest_x;
                new_y <= nearest_y;
                reached_target <= 1; // Indicates that the target has been reached
            end else begin
                new_x <= nearest_x;
                new_y <= nearest_y;
                reached_target <= 0;
            end
        end
    end
